package com.transiva.app;
import android.Manifest;import android.app.NotificationManager;import android.content.Context;import android.content.pm.PackageManager;import android.location.LocationManager;import android.os.*;import android.provider.Settings;import android.widget.*;import androidx.core.content.ContextCompat;import com.google.firebase.messaging.FirebaseMessaging;
public class MerchantDiagnosticsActivity extends MerchantBaseActivity{
 private LinearLayout list;@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);setContentView(page(root));root.addView(title("Diagnostik Merchant"));root.addView(sub("Periksa kesiapan perangkat menerima dan memproses pesanan"));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Button r=outlineBtn("↻ Periksa Ulang");r.setOnClickListener(v->run());root.addView(r);run();}
 private void run(){list.removeAllViews();boolean net=MerchantConnectivity.isOnline(this);boolean loc=ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);boolean gps=false;try{gps=lm!=null&&lm.isProviderEnabled(LocationManager.GPS_PROVIDER);}catch(Exception ignored){}boolean notif=true;if(Build.VERSION.SDK_INT>=33)notif=ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED;if(Build.VERSION.SDK_INT>=24){NotificationManager nm=(NotificationManager)getSystemService(Context.NOTIFICATION_SERVICE);notif=notif&&nm!=null&&nm.areNotificationsEnabled();}row("Internet",net,"Diperlukan untuk sinkronisasi order");row("Lokasi Presisi",loc&&gps,loc?"GPS "+(gps?"aktif":"nonaktif"):"Izin belum diberikan");row("Notifikasi",notif,"Pesanan baru membutuhkan notifikasi aktif");row("Sesi",sessionManager!=null&&sessionManager.isLoggedIn(),"Autentikasi merchant");row("Crash lokal",true,MerchantCrashReporter.summary(this));row("Versi",true,AppUpdateClient.installedVersionName(this));TextView f=card("Firebase: memeriksa token...");list.addView(f);FirebaseMessaging.getInstance().getToken().addOnCompleteListener(t->f.setText(t.isSuccessful()&&!t.getResult().isEmpty()?"✅ Firebase: token FCM tersedia":"⚠ Firebase: token belum tersedia"));}
 private void row(String n,boolean ok,String detail){list.addView(card((ok?"✅ ":"⚠ ")+n+"\n"+detail));}
}
